1	//! `ClaudeHandDispatcher` — Claude Code implementation of `HandDispatcher`.
2	//!
3	//! Each dispatch writes a self-contained queue file under `queue_dir`. When
4	//! `auto_dispatch` is on, a background task spawns `claude --print` with the
5	//! queue file piped to stdin, heartbeats the hand, and releases the ticket
6	//! back to `Ready` if the process times out. When `auto_dispatch` is off the
7	//! dispatcher just records a note pointing operators at the queue file.
8	
9	use std::path::PathBuf;
10	use std::process::Stdio;
11	use std::sync::Arc;
12	use std::time::{Duration, SystemTime, UNIX_EPOCH};
13	
14	use async_trait::async_trait;
15	use chrono::Utc;
16	use derrick_substrate::{
17	    EventKind, EventScope, Hand, HandId, HandKind, Substrate, SubstrateError, Ticket, TicketId,
18	};
19	use derrick_substrate_native::foreman::{
20	    DispatchContext, DispatchError, DispatchResult, HandDispatcher,
21	};
22	use derrick_substrate_native::NativeSubstrate;
23	use tokio::process::Command;
24	use tracing::{error, info, instrument, warn};
25	
26	use crate::prompt::render_queue_file;
