28	/// Runtime configuration for [`ClaudeHandDispatcher`]. Sourced from
29	/// `tools.claude` in `derrick.yaml`.
30	#[derive(Clone, Debug)]
31	pub struct ClaudeHandDispatcherConfig {
32	    /// When true, spawn `claude --print` automatically; otherwise just write
33	    /// the queue file and leave invocation to an operator.
34	    pub auto_dispatch: bool,
35	    /// Heartbeat interval while the background task waits on `claude`.
36	    pub poll_interval: Duration,
37	    /// Maximum wall-clock duration the background task waits before
38	    /// releasing the hand back to Ready.
39	    pub poll_timeout: Duration,
40	    /// Stable identity prefix used when minting hand ids. The dispatcher
41	    /// appends a short suffix so multiple dispatches do not collide.
42	    pub agent_identity: String,
43	    /// Prefix applied to dispatch branch names. Combined with the ticket
44	    /// batch and id to form `<prefix>/<batch>/<ticket-id>`.
45	    pub branch_prefix: String,
46	    /// Directory where queue files are written. Absolute path; the
47	    /// dispatcher creates it on demand.
48	    pub queue_dir: PathBuf,
49	    /// Default base branch when the foreman does not supply a parent (kept
50	    /// for symmetry with the Copilot dispatcher; unused in dispatch).
51	    pub base_branch: String,
52	    /// Whether to prepend Roughneck instructions to the queue file prompt.
53	    pub roughneck_enabled: bool,
54	    /// Roughneck level: "lite", "full", or "ultra".
55	    pub roughneck_level: String,
56	}
57	
58	impl Default for ClaudeHandDispatcherConfig {
59	    fn default() -> Self {
60	        Self {
61	            auto_dispatch: false,
62	            poll_interval: Duration::from_secs(60),
63	            poll_timeout: Duration::from_secs(60 * 60),
64	            agent_identity: "derrick-claude-hand".to_owned(),
65	            branch_prefix: "derrick".to_owned(),
66	            queue_dir: PathBuf::from(".derrick/queue"),
67	            base_branch: "main".to_owned(),
68	            roughneck_enabled: true,
69	            roughneck_level: "full".to_owned(),
70	        }
71	    }
72	}
