74	/// `HandDispatcher` for Claude Code. See module docs.
75	pub struct ClaudeHandDispatcher {
76	    substrate: Arc<NativeSubstrate>,
77	    config: ClaudeHandDispatcherConfig,
78	}
79	
80	impl ClaudeHandDispatcher {
81	    /// Construct a dispatcher from its substrate and config.
82	    pub fn new(substrate: Arc<NativeSubstrate>, config: ClaudeHandDispatcherConfig) -> Self {
83	        Self { substrate, config }
84	    }
85	
86	    fn target_branch(&self, ticket: &Ticket) -> String {
87	        let batch = ticket
88	            .batch
89	            .as_ref()
90	            .map(derrick_substrate::BatchName::as_str)
91	            .unwrap_or("ad-hoc");
92	        format!("{}/{}/{}", self.config.branch_prefix, batch, ticket.id)
93	    }
94	
95	    fn mint_hand_id(&self) -> Result<HandId, SubstrateError> {
96	        // HandId pattern: ^[a-z][a-z0-9-]{0,63}$. Sanitize the configured
97	        // identity, then append a short suffix derived from SystemTime.
98	        let mut cleaned: String = self
99	            .config
100	            .agent_identity
101	            .chars()
102	            .filter_map(|c| {
103	                if c.is_ascii_alphanumeric() {
104	                    Some(c.to_ascii_lowercase())
105	                } else if c == '-' {
106	                    Some('-')
107	                } else {
108	                    None
109	                }
110	            })
111	            .collect();
112	        let starts_with_letter = cleaned
113	            .chars()
114	            .next()
115	            .map(|c| c.is_ascii_lowercase())
116	            .unwrap_or(false);
117	        if !starts_with_letter {
118	            cleaned.insert_str(0, "c-");
119	        }
120	        let suffix = short_suffix();
121	        let mut raw = format!("{cleaned}-{suffix}");
122	        raw.truncate(64);
123	        HandId::new(raw)
124	    }
125	}
126	
127	fn short_suffix() -> String {
128	    let nanos = SystemTime::now()
129	        .duration_since(UNIX_EPOCH)
130	        .map(|d| d.as_nanos())
131	        .unwrap_or(0);
132	    // 6 hex chars of entropy is enough for collision resistance within
133	    // a single dispatcher process.
134	    format!("{:06x}", (nanos as u64) & 0x00ff_ffff)
135	}
