137	#[async_trait]
138	impl HandDispatcher for ClaudeHandDispatcher {
139	    fn kind(&self) -> &'static str {
140	        "claude"
141	    }
142	
143	    #[instrument(skip(self, ctx), fields(ticket_id = %ctx.ticket.id))]
144	    async fn dispatch(&self, ctx: &DispatchContext<'_>) -> Result<DispatchResult, DispatchError> {
145	        let ticket = ctx.ticket;
146	        let branch = self.target_branch(ticket);
147	
148	        // 1. Mint a hand id and register it in the substrate.
149	        let hand_id = self.mint_hand_id()?;
150	        let hand = Hand {
151	            id: hand_id.clone(),
152	            kind: HandKind::Claude,
153	            last_seen: Some(Utc::now()),
154	        };
155	        self.substrate.register_hand(hand).await?;
156	
157	        // 2. Ensure the queue dir exists and render the queue file.
158	        tokio::fs::create_dir_all(&self.config.queue_dir)
159	            .await
160	            .map_err(DispatchError::Io)?;
161	        let batch = ticket
162	            .batch
163	            .as_ref()
164	            .map(derrick_substrate::BatchName::as_str);
165	        let queue_body = render_queue_file(
166	            ticket.id.as_str(),
167	            batch,
168	            &ticket.title,
169	            &ticket.body,
170	            &branch,
171	            &ctx.parent_branch,
172	            self.config.roughneck_enabled,
173	            &self.config.roughneck_level,
174	        );
175	        let queue_file = self
176	            .config
177	            .queue_dir
178	            .join(format!("{}.md", ticket.id.as_str()));
179	        tokio::fs::write(&queue_file, &queue_body)
180	            .await
181	            .map_err(DispatchError::Io)?;
182	
183	        // 3. Atomic Ready -> InFlight + owner = hand.
184	        self.substrate.assign_to_hand(&ticket.id, &hand_id).await?;
185	
186	        // 4. Surface dispatch in the activity log.
187	        let queue_path_display = queue_file.display().to_string();
188	        let note = format!(
189	            "claude hand: queue file written to {queue_path_display}; run \
190	             'claude --print < {queue_path_display}' to dispatch"
191	        );
192	        self.substrate
193	            .record_typed_event(
194	                EventScope::Ticket(ticket.id.clone()),
195	                EventKind::Note { body: note },
196	            )
197	            .await?;
198	        info!(
199	            ticket = %ticket.id,
200	            branch = branch.as_str(),
201	            queue_file = %queue_path_display,
202	            auto_dispatch = self.config.auto_dispatch,
203	            "claude queue file written"
204	        );
205	
206	        // 5. Optionally spawn the background poll task.
207	        if self.config.auto_dispatch {
208	            let task = PollTask {
209	                substrate: Arc::clone(&self.substrate),
210	                ticket_id: ticket.id.clone(),
211	                hand_id: hand_id.clone(),
212	                queue_file: queue_file.clone(),
213	                poll_interval: self.config.poll_interval,
214	                poll_timeout: self.config.poll_timeout,
215	                roughneck_enabled: self.config.roughneck_enabled,
216	                roughneck_level: self.config.roughneck_level.clone(),
217	            };
218	            tokio::spawn(task.run());
219	        }
220	
221	        Ok(DispatchResult {
222	            hand: hand_id,
223	            completed_synchronously: false,
224	        })
225	    }
226	}
