228	/// Background task that supervises a single `claude --print` invocation.
229	struct PollTask {
230	    substrate: Arc<NativeSubstrate>,
231	    ticket_id: TicketId,
232	    hand_id: HandId,
233	    queue_file: PathBuf,
234	    poll_interval: Duration,
235	    poll_timeout: Duration,
236	    roughneck_enabled: bool,
237	    roughneck_level: String,
238	}
239	
240	impl PollTask {
241	    async fn run(self) {
242	        // Open the queue file for stdin redirection.
243	        let stdin_handle = match std::fs::File::open(&self.queue_file) {
244	            Ok(file) => file,
245	            Err(error) => {
246	                error!(
247	                    ?error,
248	                    queue_file = %self.queue_file.display(),
249	                    "failed to open queue file for claude --print"
250	                );
251	                self.release(format!(
252	                    "failed to open queue file {}: {error}",
253	                    self.queue_file.display()
254	                ))
255	                .await;
256	                return;
257	            }
258	        };
259	
260	        let mut child = match Command::new("claude")
261	            .arg("--print")
262	            .arg("--output-format")
263	            .arg("json")
264	            .stdin(Stdio::from(stdin_handle))
265	            .stdout(Stdio::piped())
266	            .stderr(Stdio::piped())
267	            .spawn()
268	        {
269	            Ok(child) => child,
270	            Err(error) => {
271	                error!(?error, "failed to spawn `claude --print`");
272	                self.release(format!("failed to spawn claude: {error}"))
273	                    .await;
274	                return;
275	            }
276	        };
277	
278	        // Drain stdout concurrently so the pipe never blocks the child.
279	        let stdout_handle = child.stdout.take().map(|mut stdout| {
280	            tokio::spawn(async move {
281	                use tokio::io::AsyncReadExt;
282	                let mut buf = Vec::new();
283	                let _ = stdout.read_to_end(&mut buf).await;
284	                buf
285	            })
286	        });
287	
288	        // Heartbeat loop interleaved with process wait.
289	        let deadline = tokio::time::Instant::now() + self.poll_timeout;
290	        loop {
291	            // Heartbeat each tick.
292	            if let Err(error) = self.substrate.hand_heartbeat(&self.hand_id).await {
293	                warn!(
294	                    ?error,
295	                    hand = %self.hand_id,
296	                    "hand_heartbeat failed during claude poll loop"
297	                );
298	            }
299	
300	            let now = tokio::time::Instant::now();
301	            if now >= deadline {
302	                warn!(
303	                    ticket = %self.ticket_id,
304	                    timeout_seconds = self.poll_timeout.as_secs(),
305	                    "claude dispatch timed out; killing process and releasing hand"
306	                );
307	                let _ = child.kill().await;
308	                self.release(format!(
309	                    "claude dispatch timed out after {}s",
310	                    self.poll_timeout.as_secs()
311	                ))
312	                .await;
313	                return;
314	            }
315	
316	            let sleep = self
317	                .poll_interval
318	                .min(deadline.saturating_duration_since(now));
319	            tokio::select! {
320	                wait = child.wait() => {
321	                    match wait {
322	                        Ok(status) if status.success() => {
323	                            info!(
324	                                ticket = %self.ticket_id,
325	                                "claude --print exited successfully"
326	                            );
327	                            let stdout_bytes = match stdout_handle {
328	                                Some(handle) => handle.await.unwrap_or_default(),
329	                                None => Vec::new(),
330	                            };
331	                            self.record_hand_stats(&stdout_bytes).await;
332	                            self.check_terminal_state().await;
333	                            return;
334	                        }
335	                        Ok(status) => {
336	                            warn!(
337	                                ticket = %self.ticket_id,
338	                                code = ?status.code(),
339	                                "claude --print exited non-zero"
340	                            );
341	                            self.release(format!(
342	                                "claude exited non-zero: {:?}",
343	                                status.code()
344	                            ))
345	                            .await;
346	                            return;
347	                        }
348	                        Err(error) => {
349	                            error!(?error, "failed to wait on claude --print");
350	                            self.release(format!("failed to wait on claude: {error}"))
351	                                .await;
352	                            return;
353	                        }
354	                    }
355	                }
356	                () = tokio::time::sleep(sleep) => {
357	                    // Loop back around for another heartbeat and timeout check.
358	                }
359	            }
360	        }
361	    }
362	
363	    async fn record_hand_stats(&self, stdout_bytes: &[u8]) {
364	        let bytes_raw = stdout_bytes.len() as u32;
365	        let scrubber = derrick_scrub::Scrubber::with_defaults();
366	        let (_scrubbed, scrub_stats) = scrubber.scrub("claude", stdout_bytes);
367	        let bytes_saved = scrub_stats
368	            .bytes_in
369	            .saturating_sub(scrub_stats.bytes_out)
370	            .min(u64::from(u32::MAX)) as u32;
371	
372	        let (tokens_in, tokens_out) =
373	            match serde_json::from_slice::<serde_json::Value>(stdout_bytes) {
374	                Ok(value) => {
375	                    let usage = value.get("usage");
376	                    let tokens_in = usage
377	                        .and_then(|u| u.get("input_tokens"))
378	                        .and_then(serde_json::Value::as_u64)
379	                        .unwrap_or(0) as u32;
380	                    let tokens_out = usage
381	                        .and_then(|u| u.get("output_tokens"))
382	                        .and_then(serde_json::Value::as_u64)
383	                        .unwrap_or(0) as u32;
384	                    (tokens_in, tokens_out)
385	                }
386	                Err(_) => (0, 0),
387	            };
388	
389	        let roughneck_saved = if self.roughneck_enabled {
390	            derrick_roughneck::estimate_tokens_saved(tokens_out, &self.roughneck_level)
391	        } else {
392	            0
393	        };
394	
395	        let body = format!(
396	            "hand stats: tokens_in={tokens_in} tokens_out={tokens_out} \
397	             roughneck_saved={roughneck_saved} bytes_raw={bytes_raw} bytes_saved={bytes_saved}"
398	        );
399	        if let Err(error) = self
400	            .substrate
401	            .record_typed_event(
402	                EventScope::Ticket(self.ticket_id.clone()),
403	                EventKind::Note { body },
404	            )
405	            .await
406	        {
407	            warn!(?error, ticket = %self.ticket_id, "failed to record hand stats note");
408	        }
409	    }
410	
411	    async fn release(&self, reason: String) {
412	        if let Err(error) = self
413	            .substrate
414	            .release_from_hand(&self.ticket_id, reason.clone())
415	            .await
416	        {
417	            warn!(
418	                ?error,
419	                ticket = %self.ticket_id,
420	                reason = %reason,
421	                "release_from_hand failed during claude cleanup"
422	            );
423	        }
424	        let _ = self
425	            .substrate
426	            .record_typed_event(
427	                EventScope::Ticket(self.ticket_id.clone()),
428	                EventKind::Note {
429	                    body: format!("claude hand released: {reason}"),
430	                },
431	            )
432	            .await;
433	    }
434	
435	    async fn check_terminal_state(&self) {
436	        match self.substrate.get_ticket(&self.ticket_id).await {
437	            Ok(Some(ticket)) => {
438	                if matches!(
439	                    ticket.state,
440	                    derrick_substrate::TicketState::InReview | derrick_substrate::TicketState::Done
441	                ) {
442	                    info!(
443	                        ticket = %self.ticket_id,
444	                        state = %ticket.state,
445	                        "claude ticket reached terminal hand state"
446	                    );
447	                } else {
448	                    warn!(
449	                        ticket = %self.ticket_id,
450	                        state = %ticket.state,
451	                        "claude --print exited 0 but ticket is not InReview; \
452	                         operator may need to run `derrick ticket review`"
453	                    );
454	                }
455	            }
456	            Ok(None) => {
457	                warn!(ticket = %self.ticket_id, "ticket not found after claude exit");
458	            }
459	            Err(error) => {
460	                warn!(?error, ticket = %self.ticket_id, "failed to read ticket after claude exit");
461	            }
462	        }
463	    }
464	}
