551	    #[tokio::test]
552	    async fn dispatch_interactive_writes_queue_file() {
553	        let tempdir = tempfile::tempdir()
554	            .map_err(|error| format!("tempdir: {error}"))
555	            .unwrap_or_else(|message| panic!("{message}"));
556	        let substrate = open_substrate(&tempdir).await;
557	        let ticket = make_ticket(&substrate, "drk-101").await;
558	        let queue_dir = tempdir.path().join("queue");
559	        let dispatcher =
560	            ClaudeHandDispatcher::new(Arc::clone(&substrate), dispatcher_config(queue_dir.clone()));
561	
562	        let result = dispatcher
563	            .dispatch(&ctx(&ticket, tempdir.path()))
564	            .await
565	            .map_err(|error| format!("dispatch: {error}"))
566	            .unwrap_or_else(|message| panic!("{message}"));
567	        assert!(!result.completed_synchronously);
568	
569	        // Queue file exists with expected content.
570	        let path = queue_dir.join("drk-101.md");
571	        let body = tokio::fs::read_to_string(&path)
572	            .await
573	            .map_err(|error| format!("read queue: {error}"))
574	            .unwrap_or_else(|message| panic!("{message}"));
575	        assert!(body.contains("derrick/ad-hoc/drk-101"));
576	        assert!(body.contains("derrick ticket review drk-101"));
577	
578	        // Ticket is now InFlight, owned by the registered hand.
579	        let refreshed = substrate
580	            .get_ticket(&ticket.id)
581	            .await
582	            .map_err(|error| format!("get: {error}"))
583	            .unwrap_or_else(|message| panic!("{message}"))
584	            .unwrap_or_else(|| panic!("ticket present"));
585	        assert_eq!(refreshed.state, TicketState::InFlight);
586	        assert_eq!(refreshed.owner.as_ref(), Some(&result.hand));
587	
588	        // Hand exists and is of kind Claude.
589	        let hands = substrate
590	            .list_hands()
591	            .await
592	            .map_err(|error| format!("list hands: {error}"))
593	            .unwrap_or_else(|message| panic!("{message}"));
594	        let registered = hands
595	            .iter()
596	            .find(|h| h.id == result.hand)
597	            .unwrap_or_else(|| panic!("hand present"));
598	        assert_eq!(registered.kind, HandKind::Claude);
599	    }
