26	/// Runtime configuration for [`CopilotHandDispatcher`]. Sourced from
27	/// `tools.copilot` in `derrick.yaml`.
28	#[derive(Clone, Debug)]
29	pub struct CopilotHandDispatcherConfig {
30	    /// Interval between successive PR polls. Default 30s.
31	    pub poll_interval: Duration,
32	    /// Maximum wall-clock duration the poll loop will wait for a PR before
33	    /// giving up. Default 10 minutes.
34	    pub poll_timeout: Duration,
35	    /// Branch name used as the base for new dispatch branches. Default
36	    /// `main`.
37	    pub base_branch: String,
38	    /// Stable identity prefix used when minting hand ids. The dispatcher
39	    /// appends a short random suffix so multiple dispatches do not collide.
40	    pub agent_identity: String,
41	    /// Prefix applied to dispatch branch names. Combined with the ticket
42	    /// batch and id to form `<prefix>/<batch>/<ticket-id>`. Sourced from
43	    /// `tools.git.branch_prefix`; defaults to `"derrick"`.
44	    pub branch_prefix: String,
45	    /// Whether to prepend Roughneck instructions to the issue body submitted
46	    /// to Copilot.
47	    pub roughneck_enabled: bool,
48	    /// Roughneck level: "lite", "full", or "ultra".
49	    pub roughneck_level: String,
50	}
51	
52	impl Default for CopilotHandDispatcherConfig {
53	    fn default() -> Self {
54	        Self {
55	            poll_interval: Duration::from_secs(30),
56	            poll_timeout: Duration::from_secs(60 * 10),
57	            base_branch: "main".to_owned(),
58	            agent_identity: "derrick-hand".to_owned(),
59	            branch_prefix: "derrick".to_owned(),
60	            roughneck_enabled: true,
61	            roughneck_level: "full".to_owned(),
62	        }
63	    }
64	}
