137	#[async_trait]
138	impl HandDispatcher for CopilotHandDispatcher {
139	    fn kind(&self) -> &'static str {
140	        "copilot"
141	    }
142	
143	    #[instrument(skip(self, ctx), fields(ticket_id = %ctx.ticket.id))]
144	    async fn dispatch(&self, ctx: &DispatchContext<'_>) -> Result<DispatchResult, DispatchError> {
145	        let ticket = ctx.ticket;
146	        let branch = self.target_branch(ticket);
147	
148	        // 1. Ensure the branch exists on the remote so Copilot can target
149	        //    it. Use the foreman-supplied parent branch so stacked tickets
150	        //    are based on their predecessor rather than the global target.
151	        self.branch_creator
152	            .ensure_branch(&branch, &ctx.parent_branch)
153	            .await
154	            .map_err(branch_error_to_dispatch)?;
155	
156	        // 2. Mint a hand id and register it in the substrate.
157	        let hand_id = self.mint_hand_id(ticket)?;
158	        let hand = Hand {
159	            id: hand_id.clone(),
160	            kind: HandKind::Copilot,
161	            last_seen: Some(Utc::now()),
162	        };
163	        self.substrate.register_hand(hand).await?;
164	
165	        // 3. File the Copilot task. If this fails the hand exists but no
166	        //    work has been dispatched — record a note and surface the
167	        //    error so the foreman can re-queue.
168	        let issue_body = if self.config.roughneck_enabled {
169	            derrick_roughneck::inject_prompt(&ticket.body, &self.config.roughneck_level)
170	        } else {
171	            ticket.body.clone()
172	        };
173	        let task = match self
174	            .client
175	            .create_task(&branch, &ticket.title, &issue_body)
176	            .await
177	        {
178	            Ok(task) => task,
179	            Err(error) => {
180	                error!(?error, "copilot create_task failed; leaving ticket Ready");
181	                let body = format!("copilot dispatch failed: {error}");
182	                self.substrate
183	                    .record_typed_event(
184	                        EventScope::Ticket(ticket.id.clone()),
185	                        EventKind::Note { body },
186	                    )
187	                    .await?;
188	                return Err(copilot_error_to_dispatch(error));
189	            }
190	        };
191	        info!(
192	            issue_number = task.issue_number,
193	            branch = branch.as_str(),
194	            "copilot task created"
195	        );
196	
197	        // 4. Atomic Ready -> InFlight + owner = hand.
198	        self.substrate.assign_to_hand(&ticket.id, &hand_id).await?;
199	        // Surface dispatch in the activity log so operators can correlate
200	        // the issue with the ticket.
201	        self.substrate
202	            .record_typed_event(
203	                EventScope::Ticket(ticket.id.clone()),
204	                EventKind::Note {
205	                    body: format!(
206	                        "copilot dispatched: issue={} branch={} task_url={}",
207	                        task.issue_number,
208	                        branch,
209	                        task.issue_url.as_deref().unwrap_or("(none)")
210	                    ),
211	                },
212	            )
213	            .await?;
214	
215	        // 5. Spawn the poll task. The task heartbeats the hand each
216	        //    iteration so the foreman's cleanup pass does not declare it
217	        //    abandoned; on success it transitions the ticket to InReview.
218	        let poll = PollTask {
219	            substrate: Arc::clone(&self.substrate),
220	            client: Arc::clone(&self.client),
221	            ticket_id: ticket.id.clone(),
222	            hand: hand_id.clone(),
223	            branch,
224	            poll_interval: self.config.poll_interval,
225	            poll_timeout: self.config.poll_timeout,
226	        };
227	        tokio::spawn(poll.run());
228	
229	        Ok(DispatchResult {
230	            hand: hand_id,
231	            completed_synchronously: false,
232	        })
233	    }
234	}
235	
236	fn branch_error_to_dispatch(error: BranchError) -> DispatchError {
237	    match error {
238	        BranchError::Io { source, .. } => DispatchError::Io(source),
239	        BranchError::NonZeroExit { .. } => {
240	            DispatchError::Io(std::io::Error::other(error.to_string()))
241	        }
242	    }
243	}
244	
245	fn copilot_error_to_dispatch(error: CopilotDispatchError) -> DispatchError {
246	    match error {
247	        CopilotDispatchError::Io { source, .. } => DispatchError::Io(source),
248	        _ => DispatchError::Io(std::io::Error::other(error.to_string())),
249	    }
250	}
251	
252	/// Background task that polls for a PR matching `branch` and transitions the
253	/// ticket to InReview when one is found.
254	pub(crate) struct PollTask {
255	    substrate: Arc<NativeSubstrate>,
256	    client: Arc<dyn CopilotDispatchClient>,
257	    ticket_id: derrick_substrate::TicketId,
258	    hand: HandId,
259	    branch: String,
260	    poll_interval: Duration,
261	    poll_timeout: Duration,
262	}
263	
264	impl PollTask {
265	    /// Run the poll loop to completion. Visible to the crate so dispatcher
266	    /// tests can drive it directly without spawning.
267	    pub(crate) async fn run(self) {
268	        let deadline = Instant::now() + self.poll_timeout;
269	        loop {
270	            // Heartbeat before each attempt so a stuck network call doesn't
271	            // make the hand look abandoned.
272	            if let Err(error) = self.substrate.hand_heartbeat(&self.hand).await {
273	                warn!(
274	                    ?error,
275	                    hand = %self.hand,
276	                    "hand_heartbeat failed during poll loop"
277	                );
278	            }
279	            match self.client.poll_pr(&self.branch).await {
280	                Ok(Some(pr)) => {
281	                    if let Err(error) = self.transition_to_in_review(pr).await {
282	                        error!(
283	                            ?error,
284	                            ticket = %self.ticket_id,
285	                            "failed to transition ticket to InReview"
286	                        );
287	                    }
288	                    return;
289	                }
290	                Ok(None) => {}
291	                Err(error) => {
292	                    warn!(?error, branch = %self.branch, "poll_pr failed; will retry");
293	                }
294	            }
295	            if Instant::now() + self.poll_interval > deadline {
296	                warn!(
297	                    ticket = %self.ticket_id,
298	                    branch = %self.branch,
299	                    timeout_seconds = self.poll_timeout.as_secs(),
300	                    "copilot poll timed out without a PR; leaving ticket InFlight for the foreman to clean up"
301	                );
302	                let _ = self
303	                    .substrate
304	                    .record_typed_event(
305	                        EventScope::Ticket(self.ticket_id.clone()),
306	                        EventKind::Note {
307	                            body: format!(
308	                                "copilot poll timed out after {}s without a PR on branch {}",
309	                                self.poll_timeout.as_secs(),
310	                                self.branch
311	                            ),
312	                        },
313	                    )
314	                    .await;
315	                return;
316	            }
317	            tokio::time::sleep(self.poll_interval).await;
318	        }
319	    }
320	
321	    async fn transition_to_in_review(
322	        &self,
323	        pr: PrInfo,
324	    ) -> Result<(), derrick_substrate::SubstrateError> {
325	        let metadata = InReviewMetadata {
326	            branch: self.branch.clone(),
327	            pr_url: Some(pr.url.clone()),
328	            pr_number: Some(pr.number),
329	            head_sha: pr.head_sha.clone(),
330	        };
331	        self.substrate
332	            .transition_to_in_review(&self.ticket_id, metadata)
333	            .await?;
334	        info!(
335	            ticket = %self.ticket_id,
336	            pr_number = pr.number,
337	            head_sha = %pr.head_sha,
338	            "copilot PR detected; ticket transitioned to InReview"
339	        );
340	        Ok(())
341	    }
342	}
