32	pub(crate) async fn execute(args: ForemanArgs) -> Result<CliExitCode, crate::CliError> {
33	    match args.command {
34	        ForemanCommand::Start(start) => foreman_start(start).await,
35	        ForemanCommand::Stop(stop) => foreman_stop(stop),
36	        ForemanCommand::Tick(tick) => foreman_tick(tick).await,
37	    }
38	}
39	
40	async fn foreman_start(args: ForemanStartArgs) -> Result<CliExitCode, crate::CliError> {
41	    let repo_root = current_repo_root()?;
42	    let config = read_config(&repo_root)?;
43	    require_native(&config)?;
44	
45	    let internal_daemon_child = args.internal_daemon_child;
46	    let mode = args.mode().unwrap_or(ForemanStartMode::Detached);
47	    match mode {
48	        ForemanStartMode::Attached => {
49	            if internal_daemon_child {
50	                // Spawned by the parent detached-start path: the parent
51	                // already wrote `mode = detached` to the foreman row; the
52	                // child just runs the loop.
53	                run_daemon_child(&repo_root, &config).await
54	            } else {
55	                start_attached(&repo_root, &config).await
56	            }
57	        }
58	        ForemanStartMode::Detached => start_detached(&repo_root, &config).await,
59	    }
60	}
61	
62	async fn start_attached(repo_root: &Path, config: &Config) -> Result<CliExitCode, crate::CliError> {
63	    let substrate = open_substrate(repo_root, config).await?;
64	    let pid = std::process::id();
65	    substrate.record_foreman_attached(pid).await?;
66	    let foreman = build_foreman(repo_root, config, Arc::clone(&substrate));
67	    let result = foreman.run_attached().await;
68	    let _ignored = substrate.record_foreman_stopped().await;
69	    drop(foreman);
70	    drop(substrate);
71	    match result {
72	        Ok(()) => Ok(CliExitCode::Success),
73	        Err(error) => Err(message(format!("foreman exited with error: {error}"))),
74	    }
75	}
