77	async fn foreman_tick(_args: ForemanTickArgs) -> Result<CliExitCode, crate::CliError> {
78	    let repo_root = current_repo_root()?;
79	    let config = read_config(&repo_root)?;
80	    require_native(&config)?;
81	    let substrate = open_substrate(&repo_root, &config).await?;
82	    let foreman = build_foreman(&repo_root, &config, Arc::clone(&substrate));
83	    let report = foreman
84	        .tick()
85	        .await
86	        .map_err(|error| message(format!("foreman tick failed: {error}")))?;
87	    println!(
88	        "tick: cleanup={} verifier={} unblocked={} dispatched={}",
89	        report.cleanup_actions.len(),
90	        report.verifier_actions.len(),
91	        report.unblocked.len(),
92	        report.dispatched.len()
93	    );
94	    Ok(CliExitCode::Success)
95	}
