97	fn build_foreman(repo_root: &Path, config: &Config, substrate: Arc<NativeSubstrate>) -> Foreman {
98	    let ttls = ForemanTtls {
99	        poll_interval: config.tools().foreman().poll_interval(),
100	        in_review_ttl: chrono::Duration::from_std(config.tools().foreman().in_review_ttl())
101	            .unwrap_or_else(|_| chrono::Duration::hours(24)),
102	        hand_ttl: chrono::Duration::from_std(config.tools().foreman().hand_ttl())
103	            .unwrap_or_else(|_| chrono::Duration::minutes(30)),
104	        worktree_ttl: chrono::Duration::from_std(config.tools().foreman().worktree_ttl())
105	            .unwrap_or_else(|_| chrono::Duration::hours(24)),
106	    };
107	    let dispatcher: Box<dyn HandDispatcher> = build_dispatcher(repo_root, config, &substrate);
108	    let stack_cfg = config.tools().git().stacking().clone();
109	    let stack_backend: Arc<dyn StackBackend> = match stack_cfg.backend() {
110	        StackBackendKind::Native => Arc::new(NativeStackBackend::new(
111	            repo_root.to_path_buf(),
112	            stack_cfg.force_push(),
113	        )),
114	        StackBackendKind::Graphite | StackBackendKind::GitSpice => Arc::new(GraphiteStackBackend),
115	        StackBackendKind::None => Arc::new(NoneStackBackend),
116	    };
117	    Foreman::new(
118	        substrate,
119	        config.clone(),
120	        Box::new(GhRepoState::new(repo_root.to_path_buf())),
121	        repo_root.to_path_buf(),
122	        dispatcher,
123	    )
124	    .with_ttls(ttls)
125	    .with_exit_when_idle(config.tools().foreman().exit_when_idle())
126	    .with_stack_backend(stack_backend, stack_cfg)
127	}
128	
129	fn build_dispatcher(
130	    repo_root: &Path,
131	    config: &Config,
132	    substrate: &Arc<NativeSubstrate>,
133	) -> Box<dyn HandDispatcher> {
134	    let copilot_enabled = config.tools().copilot().enabled();
135	    let claude_enabled = config.tools().claude().enabled();
136	    // Default to copilot when enabled, otherwise claude; falls back to the
137	    // copilot stub below when neither is on.
138	    let default_kind = if copilot_enabled {
139	        "copilot"
140	    } else if claude_enabled {
141	        "claude"
142	    } else {
143	        "copilot"
144	    };
145	    let mut multi = MultiDispatcher::new(default_kind);
146	
147	    if copilot_enabled {
148	        let copilot_config = CopilotHandDispatcherConfig {
149	            poll_interval: config.tools().copilot().poll_interval(),
150	            poll_timeout: config.tools().copilot().poll_timeout(),
151	            base_branch: "main".to_owned(),
152	            agent_identity: config.tools().copilot().agent_identity().to_owned(),
153	            branch_prefix: config.tools().git().branch_prefix().to_owned(),
154	            roughneck_enabled: config.tools().roughneck().enabled(),
155	            roughneck_level: config.tools().roughneck().level().to_owned(),
156	        };
157	        let branch_creator = Arc::new(GitBranchCreator::new(repo_root.to_path_buf()))
158	            as Arc<dyn derrick_copilot::BranchCreator>;
159	        let client = Arc::new(GhCopilotClient::new(repo_root.to_path_buf()))
160	            as Arc<dyn derrick_copilot::CopilotDispatchClient>;
161	        multi = multi.register(Box::new(CopilotHandDispatcher::new(
162	            Arc::clone(substrate),
163	            branch_creator,
164	            client,
165	            copilot_config,
166	        )));
167	    }
168	
169	    if claude_enabled {
170	        let claude_cfg = config.tools().claude();
171	        let dispatcher_config = ClaudeHandDispatcherConfig {
172	            auto_dispatch: claude_cfg.auto_dispatch(),
173	            poll_interval: claude_cfg.poll_interval(),
174	            poll_timeout: claude_cfg.poll_timeout(),
175	            agent_identity: claude_cfg.agent_identity().to_owned(),
176	            branch_prefix: config.tools().git().branch_prefix().to_owned(),
177	            queue_dir: repo_root.join(claude_cfg.queue_dir()),
178	            base_branch: "main".to_owned(),
179	            roughneck_enabled: config.tools().roughneck().enabled(),
180	            roughneck_level: config.tools().roughneck().level().to_owned(),
181	        };
182	        multi = multi.register(Box::new(ClaudeHandDispatcher::new(
183	            Arc::clone(substrate),
184	            dispatcher_config,
185	        )));
186	    }
187	
188	    if multi.is_empty() {
189	        // No dispatchers enabled: keep the stub in place so the foreman can
190	        // still tick on non-copilot workloads (e.g. human mode). The stub
191	        // returns NotImplemented, which the foreman surfaces as an event
192	        // without failing the tick.
193	        #[allow(deprecated)]
194	        let stub = CopilotStubDispatcher;
195	        Box::new(stub)
196	    } else {
197	        Box::new(multi)
198	    }
199	}
