237	// ---------- Detached daemonisation (unix) ---------------------------------
238	
239	#[cfg(unix)]
240	async fn start_detached(repo_root: &Path, config: &Config) -> Result<CliExitCode, crate::CliError> {
241	    use std::os::unix::process::CommandExt;
242	
243	    let state = state_dir(repo_root, config);
244	    fs::create_dir_all(&state).map_err(|source| crate::CliError::Io {
245	        path: state.clone(),
246	        source,
247	    })?;
248	    let pid_file = pid_path(repo_root, config);
249	    if pid_file.exists() {
250	        if let Ok(existing) = fs::read_to_string(&pid_file) {
251	            if let Ok(pid) = existing.trim().parse::<i32>() {
252	                if process_is_alive(pid) {
253	                    return Err(message(format!(
254	                        "foreman already running with pid {pid}; run `derrick foreman stop` first"
255	                    )));
256	                }
257	            }
258	        }
259	    }
260	
261	    let exe = std::env::current_exe().map_err(|source| crate::CliError::Io {
262	        path: "<self>".into(),
263	        source,
264	    })?;
265	
266	    let log = log_path(repo_root, config);
267	    let log_handle = std::fs::OpenOptions::new()
268	        .create(true)
269	        .append(true)
270	        .open(&log)
271	        .map_err(|source| crate::CliError::Io {
272	            path: log.clone(),
273	            source,
274	        })?;
275	    let log_handle_err = log_handle
276	        .try_clone()
277	        .map_err(|source| crate::CliError::Io {
278	            path: log.clone(),
279	            source,
280	        })?;
281	
282	    // Spawn the daemon child via std::process::Command. The child re-execs
283	    // `derrick foreman start --attached --__internal-daemon-child` which
284	    // skips the foreman-row write (the parent owns that). pre_exec runs in
285	    // the child after fork and before exec; we use it to setsid() so the
286	    // child detaches from the controlling terminal.
287	    let mut command = std::process::Command::new(exe);
288	    command
289	        .arg("foreman")
290	        .arg("start")
291	        .arg("--attached")
292	        .arg("--__internal-daemon-child")
293	        .current_dir(repo_root)
294	        .stdin(std::process::Stdio::null())
295	        .stdout(std::process::Stdio::from(log_handle))
296	        .stderr(std::process::Stdio::from(log_handle_err));
297	    // SAFETY: `setsid` is async-signal-safe and the only operation we
298	    // perform between fork and exec.
299	    unsafe {
300	        command.pre_exec(|| {
301	            if libc::setsid() < 0 {
302	                return Err(std::io::Error::last_os_error());
303	            }
304	            Ok(())
305	        });
306	    }
307	    let child = command.spawn().map_err(|source| crate::CliError::Io {
308	        path: "<spawn>".into(),
309	        source,
310	    })?;
311	    let child_pid = child.id();
312	    // Don't wait on the child — it should outlive us.
313	    std::mem::forget(child);
314	
315	    // Record substrate state and write pid file (still inside the parent
316	    // runtime).
317	    let substrate = open_substrate(repo_root, config).await?;
318	    substrate.record_foreman_detached(child_pid).await?;
319	    drop(substrate);
320	
321	    fs::write(&pid_file, format!("{child_pid}\n")).map_err(|source| crate::CliError::Io {
322	        path: pid_file.clone(),
323	        source,
324	    })?;
325	    println!("foreman started (pid {child_pid}); log: {}", log.display());
326	    Ok(CliExitCode::Success)
327	}
328	
329	#[cfg(not(unix))]
330	async fn start_detached(
331	    _repo_root: &Path,
332	    _config: &Config,
333	) -> Result<CliExitCode, crate::CliError> {
334	    Err(message(
335	        "foreman --detached is unix-only; use --attached on this platform",
336	    ))
337	}
338	
339	#[cfg(unix)]
340	async fn run_daemon_child(
341	    repo_root: &Path,
342	    config: &Config,
343	) -> Result<CliExitCode, crate::CliError> {
344	    // Child path: do NOT write to the foreman row (parent already did).
345	    // Just run the loop until SIGTERM/SIGINT.
346	    let substrate = open_substrate(repo_root, config).await?;
347	    let foreman = build_foreman(repo_root, config, Arc::clone(&substrate));
348	    let result = foreman.run_attached().await;
349	    let _ignored = substrate.record_foreman_stopped().await;
350	    match result {
351	        Ok(()) => Ok(CliExitCode::Success),
352	        Err(error) => Err(message(format!("foreman exited with error: {error}"))),
353	    }
354	}
355	
356	#[cfg(not(unix))]
357	async fn run_daemon_child(
358	    _repo_root: &Path,
359	    _config: &Config,
360	) -> Result<CliExitCode, crate::CliError> {
361	    Err(message("daemon child path is unix-only"))
362	}
363	
364	// ---------- Stop ----------------------------------------------------------
365	
366	#[cfg(unix)]
367	fn foreman_stop(_args: ForemanStopArgs) -> Result<CliExitCode, crate::CliError> {
368	    let repo_root = current_repo_root()?;
369	    let config = read_config(&repo_root)?;
370	    let pid_file = pid_path(&repo_root, &config);
371	    if !pid_file.exists() {
372	        return Err(message(format!(
373	            "no foreman pid file at {}",
374	            pid_file.display()
375	        )));
376	    }
377	    let contents = fs::read_to_string(&pid_file).map_err(|source| crate::CliError::Io {
378	        path: pid_file.clone(),
379	        source,
380	    })?;
381	    let pid: i32 = contents
382	        .trim()
383	        .parse()
384	        .map_err(|_| message(format!("malformed pid file {}", pid_file.display())))?;
385	
386	    // SAFETY: signalling a known pid is safe; the kernel does the check.
387	    let send_signal = |sig: libc::c_int| -> i32 { unsafe { libc::kill(pid, sig) } };
388	
389	    if !process_is_alive(pid) {
390	        let _ignored = fs::remove_file(&pid_file);
391	        println!("foreman pid {pid} not running; cleaned up pid file");
392	        return Ok(CliExitCode::Success);
393	    }
394	
395	    if send_signal(libc::SIGTERM) != 0 {
396	        return Err(message(format!("failed to send SIGTERM to pid {pid}")));
397	    }
398	
