 init_repo(&repo);

 let state_td = TempDir::new_in(tempdir.path()).expect("state td");
 let substrate = open_substrate(&state_td).await;
 let ticket = make_ticket(&substrate, "drk-503").await;
 let worktree_root = tempdir.path().join("copilot-worktrees");
