86	impl LocalCopilotHandDispatcher {
87	    /// Construct a dispatcher from its substrate and config.
88	    pub fn new(substrate: Arc<NativeSubstrate>, config: LocalCopilotHandDispatcherConfig) -> Self {
89	        Self { substrate, config }
90	    }
