92	    fn target_branch(&self, ticket: &Ticket) -> String {
93	        let batch = ticket
94	            .batch
95	            .as_ref()
96	            .map(derrick_substrate::BatchName::as_str);
97	        branch_name(&self.config.branch_prefix, batch, ticket.id.as_str())
98	    }
99	
100	    fn mint_hand_id(&self) -> Result<HandId, SubstrateError> {
101	        let mut cleaned: String = self
102	            .config
103	            .agent_identity
104	            .chars()
105	            .filter_map(|c| {
106	                if c.is_ascii_alphanumeric() {
107	                    Some(c.to_ascii_lowercase())
108	                } else if c == '-' {
109	                    Some('-')
110	                } else {
111	                    None
112	                }
113	            })
114	            .collect();
115	        let starts_with_letter = cleaned
116	            .chars()
117	            .next()
118	            .map(|c| c.is_ascii_lowercase())
119	            .unwrap_or(false);
120	        if !starts_with_letter {
121	            cleaned.insert_str(0, "c-");
122	        }
123	        let suffix = short_suffix();
124	        let mut raw = format!("{cleaned}-{suffix}");
125	        raw.truncate(64);
126	        HandId::new(raw)
127	    }
128	}
129	
130	fn short_suffix() -> String {
131	    let nanos = SystemTime::now()
132	        .duration_since(UNIX_EPOCH)
133	        .map(|d| d.as_nanos())
134	        .unwrap_or(0);
135	    format!("{:06x}", (nanos as u64) & 0x00ff_ffff)
136	}
