138	/// Render the queue file content for a local copilot dispatch.
139	#[allow(clippy::too_many_arguments)]
140	fn render_queue_file(
141	    ticket_id: &str,
142	    batch: Option<&str>,
143	    title: &str,
144	    body: &str,
145	    branch: &str,
146	    parent_branch: &str,
147	    worktree: &std::path::Path,
148	    roughneck_enabled: bool,
149	    roughneck_level: &str,
150	) -> String {
151	    let batch_display = batch.unwrap_or("(none)");
152	    let mut out = String::new();
153	    out.push_str("# Derrick ticket: ");
154	    out.push_str(title);
155	    out.push('\n');
156	    out.push('\n');
157	    out.push_str(
158	        "You are implementing a ticket dispatched by derrick's crew-mode foreman.\n\
159	         Complete ALL steps below in order. Do not stop until the final review step is done.\n",
160	    );
161	    out.push('\n');
162	    out.push_str("## Ticket metadata\n");
163	    out.push_str(&format!("- **ID**: {ticket_id}\n"));
164	    out.push_str(&format!("- **Batch**: {batch_display}\n"));
165	    out.push_str(&format!("- **Branch**: `{branch}`\n"));
166	    out.push_str(&format!("- **Base**: `{parent_branch}`\n"));
167	    out.push_str(&format!("- **Worktree**: `{}`\n", worktree.display()));
168	    out.push('\n');
169	    out.push_str("## Specification\n\n");
170	    out.push_str(body);
171	    if !body.ends_with('\n') {
172	        out.push('\n');
173	    }
174	    out.push('\n');
175	    out.push_str("## Required steps\n\n");
176	    out.push_str(&format!(
177	        "1. Work inside the worktree `{}`. The branch `{branch}` is already checked out there.\n",
178	        worktree.display()
179	    ));
180	    out.push_str(
181	        "2. Implement the specification above. Commit all changes with conventional\n   \
182	         commit messages.\n",
183	    );
184	    out.push_str(&format!(
185	        "3. Push the branch: `git push -u origin {branch}`\n"
186	    ));
187	    out.push_str("4. Capture HEAD SHA: `git rev-parse HEAD`\n");
188	    out.push_str(&format!(
189	        "5. Hand back to the foreman:\n   `derrick ticket review {ticket_id} --branch {branch} --head-sha <HEAD_SHA>`\n",
190	    ));
191	    out.push('\n');
192	    out.push_str(
193	        "**Do not open a PR yourself** — the foreman handles PR creation when stacking\n\
194	         is configured.\n",
195	    );
196	    if roughneck_enabled {
197	        derrick_roughneck::inject_prompt(&out, roughneck_level)
198	    } else {
199	        out
200	    }
201	}
